/// <reference path="../../../src/lib/workflow-defs.d.ts" />

/**
 * Verify-After-Act Workflow (Bob FM-3.3 — Verification Enforcement)
 *
 * A specialized variant of two-phase workflow targeting bob's FM-3.3
 * (VERIFICATION_FAILURE) pattern. Bob consistently claims deliverables
 * are complete without running verification commands. Text coaching
 * confirmed 0% effective (0/5 sessions).
 *
 * ## How It Works
 *
 * 1. **Phase 1 (Act)**: Bob performs the actual task. An appended reminder
 *    tells him to list every file written/modified at the end.
 * 2. **Phase 2 (Verify)**: A SEPARATE session runs where bob must `read()`
 *    every claimed deliverable and confirm it exists with correct content.
 *    The verification checklist is auto-generated from Phase 1 output.
 *
 * ## Task Format
 *
 * Just pass the task as-is — no special formatting needed.
 * The workflow wraps it in act-then-verify phases automatically.
 *
 * ```
 * agent: bob
 * Write the architecture brief for the new caching layer.
 * ```
 *
 * ## Evidence
 *
 * Based on Method #15 (Workflow Enforcement): 92% strict / 97% behavioral
 * pass rate across 38+ trials. Text coaching: 0/5 (0%) for this agent+pattern.
 */

export const name: string = "verify-after-act";

export const description: string =
  "Act-then-verify workflow for bob: Phase 1 does the work, Phase 2 verifies " +
  "all deliverables exist and are correct. Targets FM-3.3 (VERIFICATION_FAILURE).";

// ── File Path Extraction ───────────────────────────────────────────────

/** Extract file paths from Phase 1 output to build verification checklist */
function extractFilePaths(text: string): string[] {
  const paths: string[] = [];
  const seen = new Set<string>();

  // Match common file path patterns in agent output
  const patterns = [
    // Explicit file references: `path/to/file.ext`
    /`((?:agents\/|src\/|\.state\/|test\/|\.lab\/)\S+?\.\w+)`/g,
    // "wrote to", "created", "modified" patterns
    /(?:wrote|created|modified|updated|saved)\s+(?:to\s+)?[`"']?((?:agents\/|src\/|\.state\/)\S+?\.\w+)[`"']?/gi,
    // Deliverables in finish()-style output
    /path['":\s]+["']?((?:agents\/|src\/|\.state\/)\S+?\.\w+)["']?/g,
  ];

  for (const pattern of patterns) {
    let match;
    while ((match = pattern.exec(text)) !== null) {
      const p = match[1].replace(/[`"'.,;:)]+$/, "");
      if (!seen.has(p)) {
        seen.add(p);
        paths.push(p);
      }
    }
  }

  return paths;
}

// ── Workflow Execute ───────────────────────────────────────────────────

export async function execute(ctx: WorkflowContext): Promise<WorkflowResult> {
  const agent = "bob";
  const task = ctx.task.replace(/^agent:\s*\S+\s*\n?/im, "").trim();

  if (!task) {
    return ctx.escalate("No task provided for verify-after-act workflow", {});
  }

  // ── Phase 1: Act ─────────────────────────────────────────────────────

  ctx.emit({ type: "step_start", step: "phase1-act" });

  const phase1Task =
    task +
    "\n\n" +
    "---\n" +
    "⛔ IMPORTANT: At the end of your work, list EVERY file you wrote or modified:\n" +
    "```\n" +
    "Files written/modified:\n" +
    "- path/to/file1.md\n" +
    "- path/to/file2.ts\n" +
    "```\n" +
    "This list will be used for automated verification in the next phase.";

  const phase1Result = await ctx.runAgent(agent, phase1Task);

  if (phase1Result.status === "error") {
    return ctx.escalate("Phase 1 (act) failed", {
      agent,
      error: phase1Result.error,
      phase: 1,
    });
  }

  // ── Extract deliverables from Phase 1 output ────────────────────────

  const phase1Output = phase1Result.lastAssistantText ?? "";
  const filePaths = extractFilePaths(phase1Output);

  // ── Phase 2: Verify ──────────────────────────────────────────────────

  ctx.emit({ type: "step_start", step: "phase2-verify" });

  let phase2Task: string;

  if (filePaths.length > 0) {
    const checklist = filePaths
      .map((p, i) => `${i + 1}. \`read("${p}")\` — confirm file exists and content is correct`)
      .join("\n");

    phase2Task =
      `## Verification Phase\n\n` +
      `The previous phase claimed to write/modify these files:\n\n` +
      `${checklist}\n\n` +
      `Your job: **read EVERY file listed above** using \`read()\` and confirm:\n` +
      `1. The file exists (no ENOENT)\n` +
      `2. The content matches what was intended\n` +
      `3. No obvious errors or incomplete sections\n\n` +
      `For each file, report: ✅ VERIFIED or ❌ MISSING/INCORRECT with details.\n\n` +
      `If any file is missing or incorrect, report the specific issue. Do NOT claim verification without actually reading the file.`;
  } else {
    phase2Task =
      `## Verification Phase\n\n` +
      `The previous phase completed a task but did not clearly list its deliverables.\n\n` +
      `Your job:\n` +
      `1. Determine what files should have been created/modified based on this task: "${task.slice(0, 200)}"\n` +
      `2. Use \`bash("find agents/bob/workspace -mmin -5 -type f")\` to find recently modified files\n` +
      `3. \`read()\` each one and confirm it looks correct\n` +
      `4. Report: ✅ VERIFIED or ❌ MISSING/INCORRECT for each expected deliverable`;
  }

  const phase2Result = await ctx.runAgent(agent, phase2Task);

  if (phase2Result.status === "error") {
    return ctx.escalate("Phase 2 (verify) failed", {
      agent,
      error: phase2Result.error,
      phase: 2,
      deliverables: filePaths,
    });
  }

  // ── Result ─────────────────────────────────────────────────────────

  return ctx.done(
    `## Verify-After-Act Workflow Complete\n\n` +
      `**Agent**: ${agent}\n` +
      `**Deliverables found**: ${filePaths.length}\n\n` +
      `### Phase 1: Act\n` +
      `${phase1Output.slice(0, 2000)}\n\n` +
      `### Phase 2: Verify\n` +
      `${phase2Result.lastAssistantText ?? "(no output)"}\n\n` +
      `### Deliverables Checked\n` +
      (filePaths.length > 0
        ? filePaths.map((p) => `- \`${p}\``).join("\n")
        : "_(no explicit deliverables extracted — Phase 2 searched independently)_"),
  );
}
